def match(orders):
    trades = []
    buy_book = []  # list of [price, arrival_time, id, qty] sorted by price desc, then arrival_time asc
    sell_book = []  # list of [price, arrival_time, id, qty] sorted by price asc, then arrival_time asc
    order_map = {}  # id -> (side, price, qty, arrival_time) for resting orders
    arrival_time = 0

    def add_to_book(side, id, price, qty, arrival_time):
        order_map[id] = (side, price, qty, arrival_time)
        if side == 'buy':
            buy_book.append([price, arrival_time, id, qty])
            buy_book.sort(key=lambda x: (-x[0], x[1]))
        else:
            sell_book.append([price, arrival_time, id, qty])
            sell_book.sort(key=lambda x: (x[0], x[1]))

    def match_order(incoming_side, incoming_id, incoming_price, incoming_qty, is_market=False):
        nonlocal trades, arrival_time
        remaining = incoming_qty

        if incoming_side == 'buy':
            # Match against sell orders
            i = 0
            while i < len(sell_book) and remaining > 0:
                sell_price, sell_arrival, sell_id, sell_qty = sell_book[i]
                if not is_market and sell_price > incoming_price:
                    break

                trade_qty = min(remaining, sell_qty)
                trades.append([incoming_id, sell_id, sell_price, trade_qty])
                remaining -= trade_qty
                sell_book[i][3] -= trade_qty

                if sell_book[i][3] == 0:
                    del sell_book[i]
                    del order_map[sell_id]
                else:
                    i += 1
        else:
            # Match against buy orders
            i = 0
            while i < len(buy_book) and remaining > 0:
                buy_price, buy_arrival, buy_id, buy_qty = buy_book[i]
                if not is_market and buy_price < incoming_price:
                    break

                trade_qty = min(remaining, buy_qty)
                trades.append([buy_id, incoming_id, buy_price, trade_qty])
                remaining -= trade_qty
                buy_book[i][3] -= trade_qty

                if buy_book[i][3] == 0:
                    del buy_book[i]
                    del order_map[buy_id]
                else:
                    i += 1

        return remaining

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, price, qty, arr_time = order_map[order_id]
                del order_map[order_id]
                if side == 'buy':
                    buy_book[:] = [o for o in buy_book if o[2] != order_id]
                else:
                    sell_book[:] = [o for o in sell_book if o[2] != order_id]

        elif order[0] == 'limit':
            order_type, order_id, side, price, qty = order
            remaining = match_order(side, order_id, price, qty, is_market=False)
            if remaining > 0:
                add_to_book(side, order_id, price, remaining, arrival_time)

        elif order[0] == 'ioc':
            order_type, order_id, side, price, qty = order
            match_order(side, order_id, price, qty, is_market=False)

        elif order[0] == 'market':
            order_type, order_id, side, qty = order
            match_order(side, order_id, None, qty, is_market=True)

    return trades

